// Small, articulated pixel sprites. Independent wings/feet replace whole-image bobbing.
const ink='#263b2a',cream='#ffe9b6',gold='#e7b650',ochre='#a46d32',pale='#dcebd7';
const path=(d,fill,extra='')=>`<path d="${d}" fill="${fill}" ${extra}/>`;
const eye=(x,y)=>`<rect x="${x}" y="${y}" width="2" height="3" fill="${ink}"/><rect x="${x}" y="${y}" width="1" height="1" fill="#fff4d6"/>`;
const feet=`<g class="sprite-feet">${path('M10 22h2v4h-3v-1h1zm7 0h2v5h-3v-1h1zm7-1h2v4h-3v-1h1z',ink)}</g>`;
function moth(){return `<g class="moth-wing wing-left">${path('M14 13L9 6H4L2 9V14L5 17L3 20L5 25H9L14 20Z',ink)}${path('M13 14L8 8H4V13L7 17L5 20L6 23H9L13 19Z',ochre)}${path('M11 13L7 9H4V12L8 16H12ZM10 19H6V21H9Z',cream)}${path('M6 11H8V13H6ZM7 19H9V21H7Z',gold)}</g><g class="moth-wing wing-right">${path('M18 13L23 6H28L30 9V14L27 17L29 20L27 25H23L18 20Z',ink)}${path('M19 14L24 8H28V13L25 17L27 20L26 23H23L19 19Z',ochre)}${path('M21 13L25 9H28V12L24 16H20ZM22 19H26V21H23Z',cream)}${path('M24 11H26V13H24ZM23 19H25V21H23Z',gold)}</g>${path('M13 12H19V21H18V25H14V21H13Z',ink)}${path('M14 13H18V20H17V24H15V20H14Z',gold)}${path('M13 10H19V16H13Z',cream)}${eye(14,12)}${eye(17,12)}${path('M13 11V8H11V6H12V7H14V11ZM18 11V8H20V6H19V7H17V11Z',ochre)}`;}
function striped(wasp){return `<g class="flight-wings">${path(wasp?'M17 13L5 3H2V6L12 15H18Z':'M16 13L9 3H5V7L10 15H17Z',ink)}${path(wasp?'M16 12L5 4H3V5L13 13Z':'M15 12L8 4H6V7L11 13Z',pale)}${path('M18 13L13 7H11V10L15 15H19Z','#aac8b6')}</g>${feet}${path(wasp?'M4 18L12 12H20V22H12L4 25Z':'M6 15L10 12H20L24 17V22L20 25H10L6 21Z',ink)}${path(wasp?'M6 19L12 14H19V20H12L6 23Z':'M8 16L11 14H19L22 18V21L19 23H11L8 20Z',gold)}${path(wasp?'M9 17H12V22L9 23ZM15 14H17V21H15Z':'M12 14H15V23H12ZM19 15H21V22H19Z',ochre)}${path('M20 12H27L30 15V21L27 23H22L19 20V15Z',ink)}${path('M22 13H27L29 16V20L26 22H22L20 19V16Z',wasp?'#f1c650':'#f7d56c')}${eye(26,16)}${path('M26 20H28V21H26Z',ochre)}${path('M23 13V9H25V8H26V10H24V13ZM28 14V11H30V10H31V12H29V14Z',ink)}`;}
function ladybird(){return `${feet}${path('M5 12L10 7H19L25 12V22L20 26H10L5 22Z',ink)}${path('M7 13L11 9H18L23 13V21L19 24H11L7 21Z','#be5032')}${path('M8 13L12 10H17L21 13V17H8Z','#eb7850')}${path('M15 9H17V24H15ZM10 13H13V16H10ZM18 17H21V20H18ZM9 20H12V22H9Z',ink)}${path('M12 10H14V12H12Z',cream)}${path('M23 15H28L30 18V22L27 25H23L21 22V18Z',ink)}${eye(27,18)}${path('M27 23H29V24H27Z',cream)}<g class="sprite-antennae">${path('M25 16V12H27V14H26V16ZM28 17H31V15H30V16H28Z',ochre)}</g>`;}
function caterpillar(){return `${feet}<g class="crawler-body">${path('M3 18L5 14H10L13 13H17L20 15H24V24H6L3 22Z',ink)}${path('M5 18L7 15H10V22H7L5 21ZM11 17L14 14H17V22H12ZM18 18L20 16H24V22H19Z','#85a447')}${path('M7 15H10V18H7ZM14 14H17V17H14ZM20 16H23V18H20Z','#c5ce71')}</g>${path('M21 12H28L31 16V22L28 25H22L19 22V16Z',ink)}${path('M22 14H28L29 17V21L27 23H22L21 21V17Z','#a7bf5e')}${eye(26,16)}${path('M25 21H28V22H25Z',ink)}<g class="sprite-antennae">${path('M23 14V10H21V8H23V10H24V14ZM27 14V10H29V8H27V9H26V14Z',ochre)}</g>`;}
export function visitorArt(type){const draw={moth,bee:()=>striped(false),wasp:()=>striped(true),ladybird,caterpillar}[type];return draw?`<svg class="live-sprite" viewBox="0 0 32 32" aria-hidden="true" shape-rendering="crispEdges">${draw()}</svg>`:'';}
